def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = [
        'data/environment/input/monthly_precipitations_amherst.csv',
        'data/environment/input/monthly_precipitations_chatham.csv',
        'data/environment/input/monthly_precipitations_boston.csv',
        'data/environment/input/monthly_precipitations_ashburnham.csv'
    ]
    rows = []
    for p in paths:
        for fp in glob.glob(p):
            rows.append({'path': fp, 'city': os.path.basename(fp).replace('monthly_precipitations_','').replace('.csv','')})
    return pd.DataFrame(rows)

def process(precip_files):
    import pandas as pd, glob, os, re

    def infer_city(path):
        base = os.path.basename(path)
        m = re.search(r"monthly_precipitations_(.+)\.csv", base)
        return (m.group(1) if m else os.path.splitext(base)[0]).lower()

    out = []
    for path in precip_files['path']:
        city = infer_city(path)
        df = pd.read_csv(path)
        # normalize columns
        cols_l = [c.lower().strip() for c in df.columns]
        df.columns = cols_l

        # Find year and monthly columns if present
        year_col = None
        for c in df.columns:
            if c in ['year', 'yr']:
                year_col = c
                break

        month_map = {
            'jan':1,'january':1,'feb':2,'february':2,'mar':3,'march':3,'apr':4,'april':4,'may':5,
            'jun':6,'june':6,'jul':7,'july':7,'aug':8,'august':8,'sep':9,'sept':9,'september':9,
            'oct':10,'october':10,'nov':11,'november':11,'dec':12,'december':12
        }

        if year_col is not None and any(c in month_map for c in df.columns):
            # wide format: one row per year
            for mcol, mnum in month_map.items():
                if mcol in df.columns:
                    tmp = df[[year_col, mcol]].copy()
                    tmp = tmp.rename(columns={year_col:'year', mcol:'precip_raw'})
                    tmp['month'] = mnum
                    tmp['month_dt'] = pd.to_datetime(dict(year=tmp['year'].astype('Int64'), month=tmp['month'], day=1), errors='coerce')
                    tmp['city'] = city
                    out.append(tmp[['month_dt','precip_raw','city']])
        else:
            # long-ish format: try to identify date/month column + precip column
            # pick first date-like column
            date_col = None
            for c in df.columns:
                if c in ['date','month','month_dt','time','period']:
                    date_col = c
                    break
            if date_col is None:
                date_col = df.columns[0]
            # precip column: first numeric-like non-date column
            precip_col = None
            for c in df.columns:
                if c == date_col:
                    continue
                precip_col = c
                break
            if precip_col is None:
                # single column file
                tmp = pd.DataFrame({'month_dt': pd.NaT, 'precip_raw': df.iloc[:,0].astype(str)})
            else:
                tmp = df[[date_col, precip_col]].copy()
                tmp.columns = ['month_dt','precip_raw']
                tmp['month_dt'] = pd.to_datetime(tmp['month_dt'], errors='coerce')
            tmp['city'] = city
            out.append(tmp[['month_dt','precip_raw','city']])

    res = pd.concat(out, ignore_index=True)
    res['precip_raw'] = res['precip_raw'].astype(str).str.strip()
    return res

